import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Personen einladen","description":"Personen zu einem Space einladen, Einladungen verwalten und Zugriff wieder entziehen.","frontmatter":{"title":"Personen einladen","description":"Personen zu einem Space einladen, Einladungen verwalten und Zugriff wieder entziehen."},"headers":[],"relativePath":"zusammenarbeit/personen-einladen.md","filePath":"zusammenarbeit/personen-einladen.md","lastUpdated":1786087067000}'),a={name:"zusammenarbeit/personen-einladen.md"};function l(s,e,d,o,h,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="personen-einladen" tabindex="-1">Personen einladen <a class="header-anchor" href="#personen-einladen" aria-label="Permalink to &quot;Personen einladen&quot;">​</a></h1><p>Zusammenarbeit findet in ApptiveGrid immer auf Ebene eines <strong>Space</strong> statt. Sie laden Personen nicht zu einem einzelnen Grid oder Formular ein, sondern zum gesamten Space.</p><div class="warning custom-block"><p class="custom-block-title">Eine Einladung gilt für den ganzen Space</p><p>Wer Zugriff auf einen Space hat, sieht alle Grids, Seiten und Flows darin — im Rahmen seiner Rolle.</p><p>Sollen bestimmte Personen nur einen Ausschnitt sehen, gibt es zwei Wege:</p><ol><li>Die Daten in einen <strong>eigenen Space</strong> legen.</li><li>Statt einer Einladung eine <a href="/zusammenarbeit/zugriff-beschraenken">geteilte Ansicht oder ein Portal</a> bereitstellen.</li></ol></div><h2 id="eine-person-einladen" tabindex="-1">Eine Person einladen <a class="header-anchor" href="#eine-person-einladen" aria-label="Permalink to &quot;Eine Person einladen&quot;">​</a></h2><ol><li>Öffnen Sie den Space.</li><li>Wählen Sie <strong>Space teilen</strong>.</li><li>Geben Sie die E-Mail-Adresse ein.</li><li>Wählen Sie die <a href="/zusammenarbeit/rollen">Rolle</a>.</li><li>Senden Sie die Einladung ab.</li></ol><p>Die Person erhält eine E-Mail mit einem Einladungslink.</p><h2 id="einladungen-verwalten" tabindex="-1">Einladungen verwalten <a class="header-anchor" href="#einladungen-verwalten" aria-label="Permalink to &quot;Einladungen verwalten&quot;">​</a></h2><p>Der Teilen-Dialog zeigt zwei Listen:</p><ul><li><strong>Geteilt mit</strong> — Personen, die bereits Zugriff haben, mit ihrer Rolle</li><li><strong>Offene Einladungen</strong> — versendete, noch nicht angenommene Einladungen</li></ul><p>Die Rolle einer Person ändern Sie direkt in der ersten Liste. Die Änderung greift sofort.</p><h2 id="zugriff-entziehen" tabindex="-1">Zugriff entziehen <a class="header-anchor" href="#zugriff-entziehen" aria-label="Permalink to &quot;Zugriff entziehen&quot;">​</a></h2><p>Entfernen Sie die Person aus <strong>Geteilt mit</strong>. Der Zugriff endet unmittelbar.</p><div class="tip custom-block"><p class="custom-block-title">Bestehende Einträge bleiben</p><p>Einträge, die die Person angelegt hat, bleiben erhalten. In der Spalte <em>Erstellt von</em> steht weiterhin ihr Name.</p></div><div class="warning custom-block"><p class="custom-block-title">Geteilte Links bleiben aktiv</p><p>Das Entfernen einer Person beendet nur ihren Space-Zugriff. Formular- und Ansichtslinks, die sie erstellt oder erhalten hat, funktionieren weiter.</p><p>Prüfen Sie nach einem Personalwechsel die <a href="/zusammenarbeit/externe-links">Links-Übersicht</a> des Space.</p></div><h2 id="haufige-fehlermeldungen" tabindex="-1">Häufige Fehlermeldungen <a class="header-anchor" href="#haufige-fehlermeldungen" aria-label="Permalink to &quot;Häufige Fehlermeldungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Meldung</th><th>Ursache</th></tr></thead><tbody><tr><td><em>Dieser Space wird bereits mit diesem Benutzer geteilt</em></td><td>Die Person hat bereits Zugriff. Ändern Sie stattdessen ihre Rolle in der Liste <em>Geteilt mit</em>.</td></tr><tr><td><em>Spaces können nicht mit sich selbst geteilt werden</em></td><td>Sie haben Ihre eigene Adresse eingegeben.</td></tr><tr><td><em>Benutzer mit E-Mail {email} existiert nicht</em></td><td>Zu dieser Adresse gibt es kein ApptiveGrid-Konto. Prüfen Sie die Schreibweise; ansonsten muss sich die Person zuerst registrieren.</td></tr></tbody></table><h2 id="wenn-platze-nicht-ausreichen" tabindex="-1">Wenn Plätze nicht ausreichen <a class="header-anchor" href="#wenn-platze-nicht-ausreichen" aria-label="Permalink to &quot;Wenn Plätze nicht ausreichen&quot;">​</a></h2><p>Personen mit Bearbeitungsrechten belegen einen <strong>Sitzplatz</strong>. Reichen die verfügbaren Plätze nicht, meldet ApptiveGrid:</p><blockquote><p><em>Überschreitung der lizenzierten Plätze in Ihrem Tarif</em></p><p><em>Ändern Sie die Berechtigungen von Benutzern auf „Nur Lesen&quot; oder buchen Sie weitere Plätze.</em></p></blockquote><p><strong>Leserechte sind kostenfrei</strong> und belegen keinen Platz. Häufig ist das schon die Lösung: Wer nur Daten ansehen soll, braucht keine Bearbeitungsrechte.</p><p>→ <a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></p><h2 id="einladung-annehmen" tabindex="-1">Einladung annehmen <a class="header-anchor" href="#einladung-annehmen" aria-label="Permalink to &quot;Einladung annehmen&quot;">​</a></h2><p>Wer eingeladen wird, klickt den Link in der E-Mail und meldet sich an oder registriert sich. Danach erscheint der Space in seiner Übersicht unter <strong>Mit mir geteilt</strong>.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/rollen">Rollen</a></li><li><a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></li><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li></ul>',25)])])}const g=n(a,[["render",l]]);export{m as __pageData,g as default};
